import os, re

def load_grids():
    d = os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t = open(d + '/../../sessions/' + os.path.basename(d) + '.jsonl').read().replace('\\n', '\n')
    G = {}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input)\s*\((\d+)x(\d+)\):\n', t):
        k, h, w = m[1], int(m[2]), int(m[3])
        grid_text = '\n'.join(t[m.end():].split('\n')[:h])
        rows = [r.split() for r in grid_text.split('\n')]
        if len(rows) == h and all(len(r) == w and all(x.isdigit() for x in r) for r in rows):
            G[k] = [[int(x) for x in r] for r in rows]
    return G

G = load_grids()

# Check all 7 positions transform correctly
pattern = [4, 4, 0, 0, 0]

def find_7s(grid):
    result = []
    for r in range(len(grid)):
        for c in range(len(grid[r])):
            if grid[r][c] == 7:
                result.append((r, c))
    return result

input_grid = G['Demo pair 1 input']
output_grid = G['Demo pair 1 output']

input_7s = find_7s(input_grid)
print("Input 7 positions:", sorted(input_7s))

# Verify transformation: each 7 becomes "4 4 0 0 0" shifted left by 2
for r, c in sorted(input_7s):
    pattern_start = c - 2
    if 0 <= pattern_start < 5:
        expected = [output_grid[r][pattern_start+i] for i in range(5)]
        if expected != pattern:
            print(f"MISMATCH at ({r},{c}): got {expected}, expected {pattern}")
        else:
            print(f"OK at ({r},{c})")

